	private void save(String key, String value) {
		savedProperties.putIfAbsent(key, System.getProperty(key));
		System.setProperty(key, value);
	}

	private List<String> orderedRows(String query) {
		return orderedRows(query, null);
	}

	private List<String> orderedRows(String query, String forcedStrategy) {
		List<String> result = new ArrayList<>();
		try (SailRepositoryConnection connection = repository.getConnection()) {
			SailTupleQuery preparedQuery = (SailTupleQuery) connection.prepareTupleQuery(QueryLanguage.SPARQL, query);
			if (forcedStrategy != null) {
				preparedQuery.setForcedLmdbExecutionStrategy(forcedStrategy);
			}
			try (TupleQueryResult tupleResult = preparedQuery.evaluate()) {
				while (tupleResult.hasNext()) {
					BindingSet row = tupleResult.next();
					result.add(row.getValue("interest").stringValue() + "|"
							+ ((Literal) row.getValue("n")).longValue());
				}
			}
		}
		return result;
	}

	private List<String> genericOrderedRows(String query) {
		System.setProperty(NATIVE_FLAG, "false");
		try {
			return orderedRows(query);
		} finally {
			System.setProperty(NATIVE_FLAG, "true");
		}
	}

	private long count(String query) {
		try (SailRepositoryConnection connection = repository.getConnection();
				TupleQueryResult tupleResult = connection.prepareTupleQuery(QueryLanguage.SPARQL, query).evaluate()) {
			assertTrue(tupleResult.hasNext());
			return ((Literal) tupleResult.next().getValue("n")).longValue();
		}
	}

	private String groupedQueryTelemetry(String forcedStrategy) {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			SailTupleQuery query = (SailTupleQuery) connection.prepareTupleQuery(GROUPED_QUERY);
			query.setForcedLmdbExecutionStrategy(forcedStrategy);
			return query.explain(Explanation.Level.Telemetry).toString();
		}
	}

	@Test
	public void unusedValuesIdentityKeepsLegalInventoryAndExactMetadataReduction() {
		long expected;
		System.setProperty(NATIVE_FLAG, "false");
		try {
			expected = count(UNUSED_VALUES_QUERY);
		} finally {
			System.setProperty(NATIVE_FLAG, "true");
		}

		assertEquals(6L, expected, "the fixture has six distinct subjects with an interest");
		assertEquals(expected, count(UNUSED_VALUES_QUERY));
		GenericPlanNode optimized = explainUnusedValues(Explanation.Level.Optimized);
		List<String> candidates = eligibleStrategies(optimized);
		assertTrue(candidates.containsAll(List.of(LmdbNativeAttemptMetrics.PATH_ADJACENCY_AGGREGATE,
				LmdbNativeAttemptMetrics.PATH_ORDERED_DISTINCT_GROUPS,
				LmdbNativeAttemptMetrics.PATH_IR_AGGREGATE,
				LmdbNativeAttemptMetrics.PATH_IR_AGGREGATE_INTERPRETED,
				LmdbNativeAttemptMetrics.PATH_NESTED_LOOP)),
				() -> "the common inventory must retain every legal execution tier: " + optimized);
		// The relational identity must not hide exact domain metadata. That zero-row reduction is stronger than
		// the still-legal ordered scan; planning it does not require opening either IR tier as a cold trial.
		GenericPlanNode telemetry = explainUnusedValues(Explanation.Level.Telemetry);
		assertEquals(LmdbNativeAttemptMetrics.PATH_ADJACENCY_AGGREGATE, findExecutionPath(telemetry),
				"the unused one-row VALUES relation must retain the exact metadata specialist");
		String quote = findMetric(telemetry, "nativeAggregateCostQuotesEstimated");
		assertTrue(quote != null && quote.contains("\"physicalDominanceProof\":\""),
				() -> "the selected zero-row reduction needs an actual plan-owned proof: " + telemetry);
		assertEquals(0L, LmdbNativeKernelExecution.AGG_OPENED.get(),
				"a proved metadata reduction needs no row-enumerating IR trial");
	}

	private GenericPlanNode explainUnusedValues(Explanation.Level level) {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			return connection.prepareTupleQuery(UNUSED_VALUES_QUERY).explain(level).toGenericPlanNode();
		}
	}

	private static List<String> eligibleStrategies(GenericPlanNode node) {
		List<String> strategies = new ArrayList<>();
		if (node.getStrategyDecisions() != null) {
			for (var decision : node.getStrategyDecisions()) {
				if (decision.decisionPoint().contains("GROUP BY")) {
					for (var candidate : decision.candidates()) {
						if (!Boolean.FALSE.equals(candidate.canAttempt())) {
							strategies.add(candidate.strategy());
						}
					}
				}
			}
		}
		if (node.getPlans() != null) {
			for (GenericPlanNode child : node.getPlans()) {
				strategies.addAll(eligibleStrategies(child));
			}
		}
		return strategies;
	}

	private static String findExecutionPath(GenericPlanNode node) {
		return findMetric(node, LmdbNativeExplain.EXECUTION_PATH);
	}

	private static String findMetric(GenericPlanNode node, String metric) {
		String path = node.getStringMetricActual(metric);
		if (path != null) {
			return path;
		}
		if (node.getPlans() != null) {
			for (GenericPlanNode child : node.getPlans()) {
				String nested = findMetric(child, metric);
				if (nested != null) {
					return nested;
				}
			}
		}
		return null;
	}

	@Test
	public void groupedCountDistinctEngagesKernelAndMatchesGeneric() {
		List<String> expected = genericOrderedRows(GROUPED_QUERY);
		assertEquals(2, expected.size(), "fixture should produce exactly two surviving groups");
		String previousSynchronous = System.getProperty(LmdbNativeJaninoCodegen.SYNCHRONOUS_PROPERTY);
		// This explicit kernel-engagement check needs the first generated kernel to be ready before dispatch returns.
		System.setProperty(LmdbNativeJaninoCodegen.SYNCHRONOUS_PROPERTY, "true");
		try {
			String janinoTelemetry = groupedQueryTelemetry(LmdbNativeAttemptMetrics.PATH_JANINO_AGGREGATE);
			assertTrue(janinoTelemetry.contains("nativeExecutionPath=janinoAggregate"),
					() -> "forced Janino aggregate route did not execute; telemetry:\n" + janinoTelemetry);
			List<String> actual = orderedRows(GROUPED_QUERY, LmdbNativeAttemptMetrics.PATH_JANINO_AGGREGATE);
			assertTrue(LmdbNativeJaninoAggregate.PLANNED.get() > 0L, "aggregate shape was never recognized");
			assertTrue(LmdbNativeJaninoAggregate.OPENED.get() > 0L, "aggregate kernel never opened");
			assertTrue(LmdbNativeJaninoCodegen.COMPILATIONS.get() > 0L,
					"synchronous validation did not successfully compile the grouped kernel");
			assertEquals(0L, LmdbNativeJaninoCodegen.COMPILE_FAILURES.get(),
					"grouped kernel compilation failed during synchronous validation");
			assertEquals(0L, LmdbNativeJaninoCodegen.PENDING_COMPILES.get(),
					"synchronous validation left an unfinished grouped kernel compile");
			assertEquals(expected, actual);
		} finally {
			if (previousSynchronous == null) {
				System.clearProperty(LmdbNativeJaninoCodegen.SYNCHRONOUS_PROPERTY);
			} else {
				System.setProperty(LmdbNativeJaninoCodegen.SYNCHRONOUS_PROPERTY, previousSynchronous);
			}
		}
	}

	@Test
	public void countersStaySilentWhenDisabled() {
		System.setProperty(LmdbNativeJaninoCodegen.ENABLED_PROPERTY, "false");
		try {
			for (int round = 0; round < 10; round++) {
				orderedRows(GROUPED_QUERY);
			}
			assertEquals(0L, LmdbNativeJaninoAggregate.PLANNED.get());
			assertEquals(0L, LmdbNativeJaninoAggregate.OPENED.get());
		} finally {
			System.setProperty(LmdbNativeJaninoCodegen.ENABLED_PROPERTY, "true");
		}
	}
